      await check('single_select_feedback_scoring_and_shuffle',async()=>{const q=samples.single;await focusQuestion(q.id);const immediate=page.getByLabel('Immediate feedback (single-select)',{exact:true});await immediate.uncheck();const wrong=q.options.find(o=>!q.correct.includes(o.id)).id;await choose([wrong]);assert(await page.locator('.solution').count()===0,'Feedback revealed before submit');await page.getByTestId('submit-answer').click();assert((await page.locator('.feedback').innerText()).includes('Not quite'),'Incorrect response not identified');let p=await progress();assert(p.questions[q.id].events.at(-1).points===0,'Default wrong-answer scoring changed');await page.getByTestId('reset-answer').click();await choose(q.correct);await page.getByTestId('submit-answer').click();p=await progress();assert(p.questions[q.id].events.at(-1).correct===true,'Correct option ID no longer grades after shuffle');assert(p.questions[q.id].events.length===2,'Reset deleted or duplicated history');assert(await page.locator('.option-explanation').count()===q.options.length,'Missing distractor explanation');await screenshot('practice-worked-solution');await page.getByTestId('reset-answer').click();await immediate.check();await choose(q.correct);assert(await page.locator('.solution').count()===1,'Immediate single feedback did not appear');await immediate.uncheck();return {questionId:q.id};});
      await check('multi_select_requires_explicit_complete_submit',async()=>{const q=samples.multi;await focusQuestion(q.id);await page.getByLabel('Immediate feedback (single-select)',{exact:true}).check();await choose([q.correct[0]]);assert(await page.locator('.solution').count()===0,'Multi-select leaked early feedback');if(q.correct.length>1){await page.getByTestId('submit-answer').click();assert(!(await progress()).questions[q.id].events.at(-1).correct,'Incomplete answer accepted');await page.getByTestId('reset-answer').click();}else await page.getByTestId('reset-answer').click();await choose(q.correct);assert(await page.locator('.solution').count()===0,'Complete multi-select auto-submitted');await page.getByTestId('submit-answer').click();assert((await progress()).questions[q.id].events.at(-1).correct,'Complete multi-select rejected');await page.getByLabel('Immediate feedback (single-select)',{exact:true}).uncheck();return {questionId:q.id};});
