    await check('coverage_week_lecture_page_concept_drilldown',async()=>{await view('coverage');const week=page.getByLabel('Coverage week',{exact:true}),lecture=page.getByLabel('Coverage lecture',{exact:true});assert(await week.count()===1&&await lecture.count()===1,'Coverage lacks week/lecture drilldown');const first=await week.locator('option').nth(1).getAttribute('value');await week.selectOption(first);const lid=await lecture.locator('option').nth(1).getAttribute('value');await lecture.selectOption(lid);assert(await page.locator('.heatmap button').count()>0,'Filtered heatmap empty');const pageIndex=await page.evaluate(()=>{const s=RoboticsStudyApp.getState();return RoboticsStudyApp.bank.pages.filter(p=>p.sourceId===s.coverageSource&&(!s.coverageWeek||String(p.week)===s.coverageWeek)&&(!s.coverageLecture||p.lectureId===s.coverageLecture)).sort((a,b)=>a.physicalPage-b.physicalPage).slice(0,120).findIndex(p=>p.conceptIds?.length);});assert(pageIndex>=0,'No concept-bearing page in selected lecture');await page.locator('.heatmap button').nth(pageIndex).click();assert((await page.locator('#coverage-detail').innerText()).includes('Lecture '+lid),'Wrong lecture detail');assert(await page.locator('#coverage-detail .tool-record').count()>0,'Page-to-concept drilldown absent');await screenshot('coverage-drilldown');const questions=page.locator('#coverage-detail button').filter({hasText:/ · verified$/});if(await questions.count()){await questions.first().click();assert(await page.getByTestId('question').count()===1,'Coverage question link failed');}});
